from pathlib import Path
from docx import Document
folder=Path('outputs/chapter5_midterm_revision')
p=[x for x in folder.glob('*.docx') if '\u5bf9\u8c61\u52a8\u4f5c\u4e00\u81f4\u7248' in x.name][0]
TEXT={
'5.2.5':'清洁用品取放与归位任务面向家庭日常清洁过程中常用物品的取用、归位和废弃物投放。任务对象包括垃圾桶、饮料罐、海绵、清洁刷和清洁喷雾瓶。垃圾投放场景中，机器人根据指令从客厅识别并抓取饮料罐，移动至厨房垃圾桶上方后完成投放；海绵收纳场景中，机器人从台面取起海绵并放入橱柜；清洁刷和清洁喷雾瓶取用场景中，机器人打开或接近橱柜储位，分别将洗碗刷和喷雾瓶转移至台面。执行过程中，机器人需要区分圆柱形饮料罐、柔性海绵、刷柄和喷雾瓶的外观及抓取位置，结合台面、橱柜和垃圾桶的空间关系完成动作衔接。垃圾桶用于承接饮料罐，橱柜用于收纳海绵或提供清洁用品，台面作为用品取放区域。通过上述对象的规范取放，可形成覆盖清洁用品管理和生活垃圾处置的基础服务能力。',
'5.2.6':'厨房器具单件归位任务针对厨房中刀具、容器、烹饪器具和储物部件的日常使用与归置过程开展。任务对象包括削皮刀、餐刀、砧板、平底锅、混合碗、打蛋器、擀面杖、炉灶、烤箱、烤面包机下层烤盘、烹饪托盘、玻璃罐、碗、茶壶、调味罐、量杯和锅。食材处理过程中，机器人将食材从水槽转移至砧板，配合刀具完成处理后放入碗中；平底锅和炉灶用于完成蔬菜烹调，混合碗用于将不同类别的蔬菜分装。烤箱门、烤盘和烹饪托盘分别涉及关闭、推入和拉出等操作，玻璃罐涉及开柜、开罐、盛装、关罐和归回等连续动作。打蛋器、擀面杖、茶壶、调味罐、量杯和锅则在台面、抽屉或橱柜之间完成取放。机器人需依据刀柄、锅柄、碗口、罐口和托盘边缘选择合适的抓取部位，并使器具在转移和放置过程中保持稳定，从而完成厨房物品的有序使用与归位。',
'5.2.7':'养护管理任务围绕家庭养护设备和状态感知设备开展提醒、监测、控制及信息记录。任务对象包括灌溉系统、智能花盆或灌溉阀、摄像头与AI识别模块、花园灌溉系统、小型盆栽、智能体重秤、空气净化器、扫地机器人、烟雾报警器和燃气报警器。灌溉系统用于在土壤湿度偏低时发出浇水提醒，智能花盆或灌溉阀用于执行浇水开关控制；摄像头与AI识别模块用于识别植物病虫害，花园灌溉系统可依据定时信息或湿度条件进行调节，小型盆栽用于开展位置调整。智能体重秤负责记录并上传体重数据，空气净化器用于提示滤网更换，扫地机器人用于提示边刷和滤网维护，烟雾报警器用于提示电量不足，燃气报警器用于执行周期性自检提醒。该任务通过环境状态、设备状态和用户需求之间的联动，实现家庭养护信息的及时反馈与相关设备的协同控制，为居家服务提供持续性的状态保障。',
'5.2.8':'物品递送任务是指将用户指定物品从明确起点送至明确终点的室内服务过程。任务对象包括书籍、水瓶、盒装饮料、罐装物、饮料瓶和马克杯。书籍递送对应从卧室床上取书并放置到床头柜；水瓶、盒装饮料、罐装物和马克杯对应从橱柜中取出后放至台面；饮料瓶递送对应从厨房冰箱中取出两瓶饮料，送至客厅咖啡台并关闭冰箱。机器人首先依据语言指令识别物品种类和目标位置，再完成抓取、路径移动和落放等动作。对于饮料瓶等多个同类物品，需要保持规定数量并依次完成转移；对于马克杯和罐装物，需要保持稳定姿态，避免移动过程中倾倒或碰撞。书籍、饮料瓶和杯具的递送路径由室内家具位置确定，床、床头柜、橱柜、冰箱、台面和咖啡台共同构成任务中的起终点参照。该任务能够满足家庭中常见的取物、送物和指定位置摆放需求。',
'5.2.9':'整理收纳任务面向家居空间中容器、书籍及生活用品的分类和归位需求。任务对象包括密封保鲜盒、床头柜、收纳盒、收纳箱、收纳篮和纸箱。密封保鲜盒从台面放入橱柜，收纳盒用于将盒装饮料从台面归置到橱柜，床头柜用于放置从床上取下的书籍。收纳箱和纸箱用于承接客厅书架上的书籍，并放置在客厅地面的指定区域；收纳篮用于将卧室篮内物品按类别放入浴室相应位置，其中洗涤剂置于洗手池下方，卫生巾盒置于搁板，皂液器置于洗手池区域，杯子、牙刷和牙膏放置在洗手台附近。机器人在执行过程中需要识别容器开口、柜体储位、书架及浴室功能区域，完成抓取、搬运和容器内放置。对于书籍收纳，应保持书籍进入收纳箱或纸箱；对于卫浴物品整理，应使不同用品进入对应区域。该任务体现了家庭物品由临时摆放状态向固定收纳位置转换的基本过程。',
'5.2.10':'储物设施开合任务针对厨房和清洗区域常见门、抽屉、层架及烤盘等部件开展开合和推拉操作。任务对象包括冰箱层架、冰箱抽屉、冰箱门、微波炉门、普通抽屉、橱柜门、洗碗机上层架、洗碗机门、烤箱门和烤面包机烤箱门。冰箱层架操作涉及将苹果从冰箱抽屉转移至层架；冰箱抽屉、冰箱门、微波炉门、普通抽屉、橱柜门、洗碗机门和烤箱门均涉及关闭动作；洗碗机上层架需要完全推入；烤面包机烤箱门需要打开。机器人通过识别把手、边缘、门缝和开口方向确定作用位置，并沿相应方向实施平稳的拉、推或关合动作。冰箱抽屉与层架构成冷藏空间内部物品摆放场景，洗碗机和烤箱部件构成清洗、烹饪设备的操作场景，微波炉门、橱柜门和普通抽屉构成常用储物设施的操作场景。该任务使机器人能够适应不同尺度和不同开启方式的家庭储物部件，为后续取放物品提供基础条件。',
'5.2.11':'室内摆放任务针对室内装饰物、墙面固定件和拍摄设备的摆放、悬挂及连接需求开展。任务对象包括墙钉、数码相机、海报、相机三脚架和蜡烛。海报悬挂场景中，机器人将厨房台面的海报移动至指定墙钉位置，使海报与墙面固定点相对应；相机安装场景中，机器人将数码相机连接到卧室内的相机三脚架；蜡烛摆放场景中，机器人从橱柜取出蜡烛并放到台面。墙钉和海报构成墙面装饰任务中的固定关系，数码相机和相机三脚架构成拍摄设备的连接关系，蜡烛与台面构成室内陈设的摆放关系。执行过程中，机器人需根据海报边缘、墙钉位置、相机安装接口、三脚架承载部位及台面区域调整末端姿态，使对象在目标位置保持稳定。该任务覆盖室内陈设中常见的悬挂、安装和摆放操作，可用于形成面向居室布置的基础技能。',
'5.2.12':'餐具与容器摆放任务面向厨房中常用杯具、夹取工具、切配工具、勺具及容器的规范取放。任务对象包括咖啡杯、夹子、披萨刀、木勺、水罐、汤勺、洗碗刷、滤盆、盘子和铝箔纸。咖啡杯、夹子和披萨刀从橱柜取出后放至台面；木勺、水罐、汤勺、洗碗刷、滤盆和铝箔纸从台面取起后放入橱柜；盘子用于承接从平底锅中转移出的苹果。机器人需要根据杯口、夹口、刀柄、勺柄、容器边缘和滤盆开口选择相应抓取位置，并在台面和橱柜之间完成平稳转移。咖啡杯、夹子和披萨刀的摆放使台面具备餐前准备条件，木勺、水罐、汤勺、洗碗刷、滤盆和铝箔纸的归柜使厨房台面保持整洁，盘子与平底锅之间的转移体现了盛装操作。通过不同餐具和容器的取放组合，机器人能够完成厨房中常见的餐具准备、器具归置和容器摆放服务。',
'5.2.13':'衣物鞋类与玄关归位任务面向家庭衣物护理、鞋类归置及入口区域整理需求。任务对象包括棒球帽、毛巾、洗衣机、鞋子和鞋架。棒球帽清洗场景中，机器人将工具间台面的两顶棒球帽放入洗衣机，通过洗涤过程完成帽类护理；毛巾整理场景中，机器人将毛巾分别放入两个篮子；玄关归位场景中，机器人将走廊地面的两组鞋子放到走廊鞋架上，并按同类相邻方式摆放。洗衣机作为棒球帽的清洗设备，鞋架作为鞋类的固定收纳位置，篮子作为毛巾分类容器。执行时，机器人需要识别织物的柔性特征、鞋类的成对关系及鞋架的摆放空间，采用适当抓取方式完成转移。棒球帽、毛巾和鞋子分别对应清洗、分类和归位三种生活场景，既覆盖衣物鞋类的基本护理，也使玄关区域保持有序。该任务能够支撑家庭中衣物与鞋类物品的日常管理服务。',
'5.2.14':'工作学习区服务任务面向书桌、转椅及周边计算设备、输入设备、文件和文具的摆放整理需求。任务对象包括办公椅、文件夹、显示器、电脑、笔盒、笔记本、笔记本电脑、订书机、铅笔、键盘和鼠标。办公椅移动至书桌旁，显示器、键盘和鼠标分别摆放在书桌及相邻位置，电脑置于书桌下方；文件夹从转椅移至书桌并放在鼠标旁，笔记本叠放在文件夹上。笔盒用于收纳铅笔和两支笔，笔记本电脑从床上移动到书桌并关闭，订书机从书柜移动到桌面。书桌作为主要操作台面，转椅、书柜和床分别构成文件夹、订书机和笔记本电脑的起始位置。机器人需要理解显示器、键盘、鼠标、文件夹和笔记本之间的相邻关系，保持办公用品排列有序；同时依据笔盒开口和桌面区域完成文具收纳。该任务覆盖家庭工作和学习区域中常见的设备摆放、桌面整理和文具归置操作。',
'5.2.15':'卫浴用品与个人卫生服务任务面向浴室内常用卫生用品的取放、归类和摆放需求。任务对象包括卫浴搁板、卫生巾盒、固体香皂、洗涤剂、牙刷、牙膏和皂液器。卫生巾盒从卧室篮中取出后放到浴室搁板；固体香皂从台面放入橱柜；洗涤剂从卧室篮中取出后放在洗手池下方；牙刷和牙膏放入洗手台上的杯中；皂液器从橱柜取出后放到台面。卫浴搁板、洗手池下方、洗手台杯子、橱柜和台面构成不同用品的功能区域，其中搁板用于放置卫生巾盒，洗手池下方用于存放洗涤剂，杯子用于集中收纳牙刷和牙膏，橱柜与台面用于完成香皂和皂液器的取放。机器人执行时需要识别物品类别及各功能区域的空间位置，保持牙刷、牙膏等细长对象在杯内稳定放置。该任务体现了卫生用品由临时位置向固定卫浴储位转移的日常服务过程。'
}
d=Document(p)
for code,text in TEXT.items():
    i=next(i for i,x in enumerate(d.paragraphs) if x.text.strip().startswith(code))
    body=d.paragraphs[i+1]
    body.clear(); body.add_run(text)
d.save(p)
print('updated',p.name)
